CREATE INDEX `collaboration_tasks_pending_workflow` ON `collaboration_tasks` (`updated_at`,`id`) WHERE "collaboration_tasks"."active" = 1 AND json_extract("collaboration_tasks"."state_json", '$.protocol') = 'native-workflow-v1' AND json_extract("collaboration_tasks"."state_json", '$.automation') = 'active' AND json_extract("collaboration_tasks"."state_json", '$.status') = 'waiting';